package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;
public class InteroperabilityActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Interoperability & API Registry","Department connectors are represented as versioned, authenticated API contracts.");DatabaseManager m=new DatabaseManager(this);Cursor c=m.getDatabase().rawQuery("SELECT api_name,department,endpoint,method,version,auth_scheme,status FROM api_registry ORDER BY id",null);try{while(c.moveToNext()){LinearLayout box=utils.column(this);box.addView(utils.text(this,c.getString(0),17,utils.TEXT,true));utils.row(box,this,"Department",c.getString(1));utils.row(box,this,"Method",c.getString(3));utils.row(box,this,"Version",c.getString(4));utils.row(box,this,"Auth",c.getString(5));box.addView(utils.text(this,c.getString(2),12,utils.BLUE,false));box.addView(utils.badge(this,c.getString(6),true));utils.addCard(root,box,this);}}finally{c.close();}utils.setScreenContentView(this, root);}
}
